import {STORAGE_KEY,DAYS,CATEGORIES,uid,dateKey,asDate,addDays,monday,weekDays,todayKey,isFor,recordsInWeek,upsert,removeRecord,calendarNotice,seedState,validateState,calendarICS} from './model.mjs';

const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-6v-7h-4v7H4a1 1 0 0 1-1-1Z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M16 3v4M8 3v4M3 11h18"/>',check:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="m7 12 3 3 7-7"/>',cart:'<path d="M2 3h3l3 12h11l3-9H6M9 20h.01M18 20h.01"/><circle cx="9" cy="20" r="1"/><circle cx="18" cy="20" r="1"/>',family:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M21 21v-3a6 6 0 0 0-4-5"/>',settings:'<path d="m9 3-.5 3-2 1-3-.5L2 11l2.5 2L5 16l-1 3 4 2 2-2h3l2 2 4-2-1-3 .5-3L22 11l-1.5-4.5-3 .5-2-1L15 3Z"/><circle cx="12" cy="12" r="3"/>',plus:'<path d="M12 5v14M5 12h14"/>',left:'<path d="m15 6-6 6 6 6"/>',right:'<path d="m9 6 6 6-6 6"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7a2 2 0 0 0-4-4L5 15Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',leaf:'<path d="M20 3C6 2 1 9 6 15s15 3 14-12ZM4 21 15 9"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.info}</svg>`;
const navs=[['visao-geral','Visão geral','home'],['calendario','Calendário','calendar'],['tarefas','Tarefas','check'],['compras','Lista de compras','cart'],['familia','Família','family']];
const app=$('#app'),modal=$('#modal');
let data,storageOK=true;
try {const saved=localStorage.getItem(STORAGE_KEY);data=saved?validateState(JSON.parse(saved)):seedState();} catch { data=seedState();storageOK=false; }
const ui={anchor:todayKey(),scope:'family',member:'all',search:'',status:'all',category:'all',calendarView:'week',taskView:'week',shoppingView:'week'};
let dialogState=null,toastTimer,searchTimer;
function route(){const key=location.hash.slice(1);return [...navs.map(n=>n[0]),'configuracoes','avisos'].includes(key)?key:'visao-geral';}
function save(message){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(data));storageOK=true;}catch{storageOK=false;message='Não foi possível salvar neste navegador. Baixe uma cópia em Configurações.';}render();if(message)toast(message);}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500);}
function current(){return data.members.find(m=>m.id===data.currentMember)||data.members[0];}
function activeMember(){return ui.scope==='mine'?current().id:ui.member;}
function member(id){return data.members.find(m=>m.id===id);}
function avatar(m,size=''){if(!m)return '';return `<span class="avatar ${size} ${esc(m.color)}" title="${esc(m.name)}">${m.avatar!=='initials'?`<img src="./assets/${esc(m.avatar)}.svg" alt="" width="36" height="36">`:`<span aria-hidden="true">${esc(m.name.slice(0,2).toUpperCase())}</span>`}</span>`;}
function people(record,compact=false){if(record.members.includes('all'))return `<span class="people all">${icon('family')}<span>Todos</span></span>`;const ms=record.members.map(member).filter(Boolean);return `<span class="people">${ms.map(m=>avatar(m,'tiny')).join('')}<span>${esc(ms.map(m=>m.name).join(' e '))}</span></span>`;}
function tone(record){return record.members.includes('all')?'sage':(member(record.members[0])?.color||'sage');}
function fmtDate(key,opts={day:'numeric',month:'long'}){return asDate(key).toLocaleDateString('pt-BR',opts);}
function weekLabel(){const days=weekDays(ui.anchor),s=asDate(days[0]),e=asDate(days[6]);if(s.getMonth()===e.getMonth())return `${s.getDate()} a ${fmtDate(days[6],{day:'numeric',month:'long',year:'numeric'})}`;return `${fmtDate(days[0],{day:'numeric',month:'short'})} a ${fmtDate(days[6],{day:'numeric',month:'short',year:'numeric'})}`;}
function isMonth(){return route()==='calendario'&&ui.calendarView==='month';}
function viewTitle(){return isMonth()?fmtDate(ui.anchor,{month:'long',year:'numeric'}):weekLabel();}
function weekbar(extra=''){return `<div class="weekbar"><div class="week-navigation"><button class="icon-button" data-action="prev" aria-label="${isMonth()?'Mês':'Semana'} anterior">${icon('left')}</button><h2>${esc(viewTitle())}</h2><button class="icon-button" data-action="next" aria-label="${isMonth()?'Próximo mês':'Próxima semana'}">${icon('right')}</button></div><div class="week-tools"><button class="button subtle small" data-action="today">${isMonth()?'Este mês':'Esta semana'}</button><label class="date-jump" title="Ir para uma data">${icon('calendar')}<input type="date" aria-label="Ir para uma data" value="${esc(ui.anchor)}" data-action="jump-date"></label>${extra}</div></div>`;}
function segment(group,options,selected){return `<div class="segmented" role="group" aria-label="${esc(group)}">${options.map(([val,label])=>`<button data-action="segment" data-group="${esc(group)}" data-value="${val}" aria-pressed="${val===selected}" class="${val===selected?'selected':''}">${esc(label)}</button>`).join('')}</div>`;}
function scopeFilter(){return `<div class="scopebar">${segment('scope',[['family','Toda a família'],['mine','Minha visão']],ui.scope)}${ui.scope==='family'?`<label class="select-wrap"><span class="sr-only">Filtrar por integrante</span><select data-action="member-filter"><option value="all">Integrante: Todos</option>${data.members.map(m=>`<option value="${esc(m.id)}" ${ui.member===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><div class="member-legend">${data.members.slice(0,5).map(m=>`<button class="person-filter ${ui.member===m.id?'active':''}" data-action="filter-person" data-id="${esc(m.id)}" aria-label="Ver itens de ${esc(m.name)}" aria-pressed="${ui.member===m.id}">${avatar(m)}<span>${esc(m.name)}</span></button>`).join('')}</div>`:`<span class="current-profile">${avatar(current())}<span>${esc(current().name)}</span><span class="muted">· seu espaço na semana</span></span>`}</div>`;}
function boardHeader(date,index){return `<div class="day-header ${date===todayKey()?'is-today':''}"><span>${DAYS[index]} <strong>${asDate(date).getDate().toString().padStart(2,'0')}</strong></span>${date===todayKey()?'<span class="today-badge">Hoje</span>':''}</div>`;}
function eventCard(e,style=''){return `<button class="event-card ${tone(e)}" data-action="edit" data-type="events" data-id="${esc(e.id)}" ${style?`style="${style}"`:''} aria-label="Editar ${esc(e.title)}, ${esc(e.time)}"><span class="event-time">${esc(e.time)}${style?` – ${esc(e.end)}`:''}</span><span class="event-title">${esc(e.title)}</span>${people(e)}</button>`;}
function taskCard(t){return `<article class="item-card ${t.done?'done':''}"><div class="item-line"><input class="check" type="checkbox" data-action="toggle" data-type="tasks" data-id="${esc(t.id)}" ${t.done?'checked':''} aria-label="${t.done?'Reabrir':'Concluir'} tarefa: ${esc(t.title)}"><button class="item-title" data-action="edit" data-type="tasks" data-id="${esc(t.id)}">${esc(t.title)}</button></div><div class="item-meta">${people(t)}${!t.done&&t.date<todayKey()?`<span class="overdue">${icon('clock')}Em atraso</span>`:''}</div></article>`;}
function shoppingCard(t){return `<article class="item-card shopping-item ${t.done?'done':''}"><div class="item-line"><input class="check" type="checkbox" data-action="toggle" data-type="shopping" data-id="${esc(t.id)}" ${t.done?'checked':''} aria-label="${t.done?'Marcar como não comprado':'Marcar como comprado'}: ${esc(t.title)}"><button class="item-title" data-action="edit" data-type="shopping" data-id="${esc(t.id)}">${esc(t.title)}</button></div><span class="quantity">${esc(t.qty||'Sem quantidade')}</span></article>`;}
function weeklyBoard(type,records,compact=false){const days=weekDays(ui.anchor);return `<div class="scroll-hint">${icon('arrow')} Deslize para ver todos os dias da semana</div><div class="board-scroll" tabindex="0" role="region" aria-label="${type==='events'?'Compromissos':type==='tasks'?'Tarefas':'Compras'} de segunda a domingo"><div class="weekly-board ${compact?'compact':''}">${days.map((date,i)=>{const rs=records.filter(r=>r.date===date).sort((a,b)=>type==='events'?a.time.localeCompare(b.time):Number(a.done)-Number(b.done));return `<section class="day-column ${date===todayKey()?'is-today':''}">${boardHeader(date,i)}<div class="day-items">${rs.length?rs.map(r=>type==='events'?eventCard(r):type==='tasks'?taskCard(r):shoppingCard(r)).join(''):`<span class="empty-day">${type==='events'?'Sem compromissos':type==='tasks'?'Tudo tranquilo':'Sem itens'}</span>`}</div><button class="day-add" data-action="new" data-type="${type}" data-date="${date}" aria-label="Adicionar ${type==='events'?'compromisso':type==='tasks'?'tarefa':'item'} em ${fmtDate(date)}">${icon('plus')}<span>${type==='events'?'Compromisso':type==='tasks'?'Tarefa':'Item'}</span></button></section>`;}).join('')}</div></div>`;}
function footer(text,ic='info'){return `<div class="info-strip">${icon(ic)}<span>${text}</span></div>`;}
function sectionHeader(title,ic,type,link){return `<div class="section-header"><h2>${icon(ic)}${title}</h2><div class="section-actions">${link?`<a class="text-link" href="#${link}">Ver ${type==='events'?'calendário':type==='tasks'?'tarefas':'lista'} ${icon('arrow')}</a>`:''}<button class="button subtle small" data-action="new" data-type="${type}">${icon('plus')}<span>${type==='events'?'Compromisso':type==='tasks'?'Tarefa':'Item'}</span></button></div></div>`;}
function overview(){const ev=recordsInWeek(data.events,ui.anchor,activeMember()),ts=recordsInWeek(data.tasks,ui.anchor,activeMember()),sh=recordsInWeek(data.shopping,ui.anchor);return `${scopeFilter()}${weekbar()}<div class="week-summary"><span>${icon('calendar')}<strong>${ev.length}</strong> compromissos</span><span>${icon('check')}<strong>${ts.filter(t=>!t.done).length}</strong> tarefas pendentes</span><span>${icon('cart')}<strong>${sh.filter(s=>!s.done).length}</strong> itens para comprar</span></div><section class="panel">${sectionHeader(ui.scope==='mine'?'Meus compromissos':'Calendário da semana','calendar','events','calendario')}${weeklyBoard('events',ev,true)}</section><section class="panel">${sectionHeader(ui.scope==='mine'?'Minhas tarefas':'Tarefas da semana','check','tasks','tarefas')}${weeklyBoard('tasks',ts,true)}</section><section class="panel">${sectionHeader('Compras da semana <span class="tag lavender">Compartilhada</span>','cart','shopping','compras')}${ui.scope==='mine'?'<p class="section-caption">A lista de compras continua compartilhada com toda a família.</p>':''}${weeklyBoard('shopping',sh,true)}</section>${footer('Avisos do calendário por e-mail: neste protótipo, você pode conferir as prévias na campainha.','mail')}`;}
function minutes(t){const [h,m]=t.split(':').map(Number);return h*60+m;}
function positionEvents(events){const sorted=[...events].sort((a,b)=>a.time.localeCompare(b.time));let result=[],group=[],until=-1;const flush=()=>{const lanes=[];const items=group.map(e=>{let lane=lanes.findIndex(end=>end<=minutes(e.time));if(lane<0)lane=lanes.length;lanes[lane]=minutes(e.end);return {...e,lane};});result.push(...items.map(e=>({...e,lanes:lanes.length})));group=[];};for(const e of sorted){if(group.length&&minutes(e.time)>=until)flush();if(!group.length)until=-1;group.push(e);until=Math.max(until,minutes(e.end));}if(group.length)flush();return result;}
function calendarWeek(events){const days=weekDays(ui.anchor);let start=Math.min(8,...events.map(e=>Math.floor(minutes(e.time)/60))),end=Math.max(21,...events.map(e=>Math.ceil(minutes(e.end)/60)));const hours=Array.from({length:end-start+1},(_,i)=>start+i),height=(end-start)*58;return `<div class="scroll-hint">${icon('arrow')} Deslize para ver os sete dias</div><div class="board-scroll timeline-scroll" tabindex="0" role="region" aria-label="Calendário semanal com horários"><div class="timeline"><div class="time-heading"></div>${days.map(boardHeader).join('')}<div class="time-labels" style="height:${height}px">${hours.map(h=>`<span style="top:${(h-start)*58}px">${String(h).padStart(2,'0')}:00</span>`).join('')}</div>${days.map(date=>`<div class="timeline-day ${date===todayKey()?'is-today':''}" style="height:${height}px">${hours.map(h=>`<div class="hour-line" style="top:${(h-start)*58}px"></div>`).join('')}${positionEvents(events.filter(e=>e.date===date)).map(e=>eventCard(e,`top:${(minutes(e.time)-start*60)/60*58}px;height:${Math.max(45,(minutes(e.end)-minutes(e.time))/60*58-3)}px;left:calc(${e.lane/e.lanes*100}% + 4px);width:calc(${100/e.lanes}% - 8px)`)).join('')}<button class="timeline-add" data-action="new" data-type="events" data-date="${date}" aria-label="Adicionar compromisso em ${fmtDate(date)}">${icon('plus')}</button></div>`).join('')}</div></div>`;}
function calendarMonth(){const d=asDate(ui.anchor),first=dateKey(new Date(d.getFullYear(),d.getMonth(),1,12)),last=dateKey(new Date(d.getFullYear(),d.getMonth()+1,0,12)),start=monday(first),count=(Math.floor((asDate(last)-asDate(start))/86400000)+1)>35?42:35;return `<div class="board-scroll"><div class="month-board">${DAYS.map(n=>`<div class="month-label">${n}</div>`).join('')}${Array.from({length:count},(_,i)=>{const date=addDays(start,i),rs=data.events.filter(e=>e.date===date&&isFor(e,activeMember())).sort((a,b)=>a.time.localeCompare(b.time));return `<section class="month-day ${date.slice(0,7)!==first.slice(0,7)?'outside':''} ${date===todayKey()?'is-today':''}"><div class="month-date"><span>${asDate(date).getDate()}</span><button class="icon-button tiny-button" data-action="new" data-type="events" data-date="${date}" aria-label="Adicionar compromisso em ${fmtDate(date)}">${icon('plus')}</button></div>${rs.map(e=>`<button class="month-event ${tone(e)}" data-action="edit" data-type="events" data-id="${esc(e.id)}">${esc(e.time)} ${esc(e.title)}</button>`).join('')}</section>`;}).join('')}</div></div>`;}
function calendarPage(){const events=recordsInWeek(data.events,ui.anchor,activeMember());return `${scopeFilter()}${weekbar(segment('calendarView',[['week','Semana'],['month','Mês']],ui.calendarView))}<div class="calendar-toolbar"><span class="muted">${isMonth()?'Visão do mês':'Cada compromisso, no seu horário.'}</span><button class="text-link" data-action="export-calendar">${icon('download')}Baixar calendário (.ics)</button></div><section class="panel calendar-panel">${isMonth()?calendarMonth():calendarWeek(events)}</section>${footer('Criar, editar ou excluir um compromisso gera uma prévia de e-mail para os integrantes que recebem avisos.','mail')}`;}
function searchBox(placeholder){return `<label class="search-box">${icon('search')}<input type="search" data-search placeholder="${placeholder}" value="${esc(ui.search)}" aria-label="${placeholder}"></label>`;}
function statusFilter(shopping=false){return segment('status',[['all','Todos'],['pending',shopping?'Falta comprar':'Pendentes'],['done',shopping?'Comprados':'Concluídas']],ui.status);}
function filtered(records){const q=ui.search.trim().toLocaleLowerCase('pt-BR');return records.filter(t=>(!q||t.title.toLocaleLowerCase('pt-BR').includes(q))&&(ui.status==='all'||(ui.status==='done'?t.done:!t.done)));}
function tasksPage(){const all=recordsInWeek(data.tasks,ui.anchor,activeMember()),ts=filtered(all);return `${scopeFilter()}<div class="filterbar">${statusFilter()}${searchBox('Buscar tarefa')}</div>${weekbar(segment('taskView',[['week','Semana'],['list','Lista']],ui.taskView))}<div class="week-summary"><span><strong>${all.length}</strong> tarefas na semana</span><span><span class="status-dot peach"></span>${all.filter(x=>!x.done).length} pendentes</span><span><span class="status-dot sage"></span>${all.filter(x=>x.done).length} concluídas</span></div><section class="panel">${!ts.length?empty('Nenhuma tarefa por aqui',ui.search||ui.status!=='all'?'Experimente outros filtros ou outra semana.':'Adicione uma tarefa e escolha quem vai ajudar.','tasks'):ui.taskView==='week'?weeklyBoard('tasks',ts):taskList(ts)}</section>${footer('Marque uma tarefa quando terminar. Para editar, clique no nome.','check')}`;}
function taskList(ts){return `<div class="list-table"><div class="list-head"><span>Tarefa</span><span>Responsável</span><span>Data</span></div>${[...ts].sort((a,b)=>a.date.localeCompare(b.date)).map(t=>`<div class="list-row ${t.done?'done':''}"><div class="item-line"><input class="check" type="checkbox" ${t.done?'checked':''} data-action="toggle" data-type="tasks" data-id="${esc(t.id)}" aria-label="Concluir ou reabrir ${esc(t.title)}"><button class="item-title" data-action="edit" data-type="tasks" data-id="${esc(t.id)}">${esc(t.title)}</button></div>${people(t)}<span class="muted">${fmtDate(t.date,{weekday:'short',day:'numeric',month:'short'})}</span></div>`).join('')}</div>`;}
function shoppingPage(){const all=recordsInWeek(data.shopping,ui.anchor),sh=filtered(all).filter(t=>ui.category==='all'||t.category===ui.category);return `<div class="shared-banner">${icon('family')}<span>Compartilhada com toda a família</span><div class="avatar-stack">${data.members.slice(0,5).map(m=>avatar(m,'tiny')).join('')}</div></div><div class="filterbar">${statusFilter(true)}<label class="select-wrap"><span class="sr-only">Categoria</span><select data-action="category"><option value="all">Categoria: Todas</option>${CATEGORIES.map(c=>`<option ${c===ui.category?'selected':''}>${c}</option>`).join('')}</select></label>${searchBox('Buscar item')}</div>${weekbar(segment('shoppingView',[['week','Semana'],['category','Por categoria']],ui.shoppingView))}<form id="quick-add" class="quick-add"><label class="quick-title"><span class="sr-only">Nome do item</span>${icon('plus')}<input name="title" required maxlength="120" placeholder="O que precisamos comprar?"></label><label><span class="sr-only">Quantidade</span><input name="qty" maxlength="50" placeholder="Quantidade"></label><label><span class="sr-only">Dia da compra</span><input name="date" type="date" value="${esc(weekDays(ui.anchor).includes(todayKey())?todayKey():monday(ui.anchor))}" required aria-label="Dia da compra"></label><button class="button primary" type="submit">Adicionar</button></form><div class="week-summary"><span><strong>${all.length}</strong> itens na semana</span><span><span class="status-dot peach"></span>${all.filter(x=>!x.done).length} faltam comprar</span><span><span class="status-dot sage"></span>${all.filter(x=>x.done).length} comprados</span></div><section class="panel">${!sh.length?empty('A lista está tranquila',ui.search||ui.status!=='all'||ui.category!=='all'?'Nenhum item corresponde aos filtros.':'Adicione o que a família precisa nesta semana.','shopping'):ui.shoppingView==='week'?weeklyBoard('shopping',sh):categoryList(sh)}</section>${footer('Qualquer integrante pode adicionar itens e marcar o que já foi comprado. Neste protótipo, as alterações ficam neste navegador.','family')}`;}
function categoryList(sh){return `<div class="category-grid">${CATEGORIES.filter(c=>sh.some(s=>s.category===c)).map(c=>`<section class="category-group"><h3>${c}<span class="tag">${sh.filter(s=>s.category===c&&!s.done).length} pendentes</span></h3>${sh.filter(s=>s.category===c).map(s=>`<div class="category-item">${shoppingCard(s)}<span class="muted">${fmtDate(s.date,{weekday:'short',day:'numeric',month:'short'})}</span></div>`).join('')}</section>`).join('')}</div>`;}
function empty(title,text,type){return `<div class="empty-state">${icon(type==='events'?'calendar':type==='tasks'?'check':type==='shopping'?'cart':'mail')}<h3>${title}</h3><p>${text}</p>${type?`<button class="button subtle" data-action="new" data-type="${type}">${icon('plus')}Adicionar ${type==='events'?'compromisso':type==='tasks'?'tarefa':'item'}</button>`:''}</div>`;}
function familyPage(){return `<div class="intro-note">${icon('leaf')}<div><strong>Todo mundo tem seu lugar.</strong><p>Escolha o perfil no canto superior para experimentar a visão de cada integrante.</p></div></div><div class="family-grid">${data.members.map(m=>`<article class="member-card"><div class="member-top">${avatar(m,'large')}<button class="icon-button" data-action="edit" data-type="members" data-id="${esc(m.id)}" aria-label="Editar ${esc(m.name)}">${icon('edit')}</button></div><h2>${esc(m.name)}${m.id===current().id?'<span class="tag sage">Você</span>':''}</h2><p class="email-label">${esc(m.email||'Sem e-mail cadastrado')}</p><p class="member-notify">${icon('mail')}${m.notify?'Recebe avisos do calendário':'Avisos desativados'}</p><button class="button subtle full-width" data-action="use-profile" data-id="${esc(m.id)}">${m.id===current().id?'Ver minha semana':`Ver como ${esc(m.name)}`}${icon('arrow')}</button></article>`).join('')}<button class="member-card add-member" data-action="new" data-type="members">${icon('plus')}<span>Adicionar integrante</span><small>Nome, perfil e preferências</small></button></div>${footer('Os perfis são demonstrativos e ficam neste navegador. Login e convites reais serão conectados na próxima etapa.','info')}`;}
function settingsPage(){return `<section class="settings-panel panel"><div class="section-header"><h2>Do seu jeito</h2></div><div class="setting-row"><div><h3>Texto maior</h3><p>Mais conforto para ler e encontrar as informações.</p></div><label class="switch"><input type="checkbox" data-action="setting" data-key="largeText" ${data.settings.largeText?'checked':''} aria-label="Usar texto maior"><span></span></label></div><div class="setting-row"><div><h3>Prévias de e-mail</h3><p>Crie prévias dos avisos ao alterar o calendário. Nenhum e-mail é enviado.</p></div><label class="switch"><input type="checkbox" data-action="setting" data-key="emailPreviews" ${data.settings.emailPreviews?'checked':''} aria-label="Gerar prévias de e-mail"><span></span></label></div><div class="setting-row"><div><h3>Perfil em uso</h3><p>A visão individual acompanha o integrante selecionado.</p></div><select data-action="profile" aria-label="Selecionar perfil">${data.members.map(m=>`<option value="${esc(m.id)}" ${m.id===current().id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div></section><section class="settings-panel panel"><div class="section-header"><h2>Seus dados</h2></div><p class="settings-copy">As alterações são salvas somente neste navegador. Para levar os dados a outro navegador, baixe uma cópia e importe no outro dispositivo. Não há sincronização automática entre familiares nesta versão.</p><div class="settings-buttons"><button class="button subtle" data-action="export-data">${icon('download')}Baixar cópia dos dados</button><label class="button outline file-label">Importar cópia<input type="file" accept=".json,application/json" id="import-file"></label></div><div class="setting-row"><div><h3>Recomeçar a demonstração</h3><p>Substitui os dados salvos pelos exemplos de uma nova semana.</p></div><button class="button danger-outline" data-action="reset">Restaurar exemplos</button></div></section><section class="prototype-note"><span class="tag sage">Protótipo interativo · 1.0</span><h3>Um primeiro passo para organizar a família.</h3><p>Calendário, tarefas, compras e perfis já podem ser testados. Compartilhamento entre contas e envio real de e-mails precisam de uma integração com login, banco de dados e serviço de e-mail.</p></section>`;}
function noticeBody(n){return `Olá, família!\n\nO compromisso “${n.eventTitle}” foi ${n.action}.\n\nData: ${fmtDate(n.date,{day:'numeric',month:'long',year:'numeric'})}\nHorário: ${n.time} às ${n.end}\n\nConfira a organização da semana no FamilyCalendar.\n\nAté lá,\nFamilyCalendar 1.0`;} 
function noticesPage(){return `<div class="notification-note">${icon('mail')}<p>Estas são <strong>prévias de e-mail</strong>, geradas pelas alterações do calendário. Nenhuma mensagem foi enviada.</p></div>${data.notices.length?`<div class="notice-tools"><span class="muted">${data.notices.length} prévias</span><button class="text-link" data-action="read-all">Marcar todas como lidas</button></div><section class="panel notice-list">${data.notices.map(n=>`<button class="notice-row ${n.read?'':'unread'}" data-action="notice" data-id="${esc(n.id)}"><span class="notice-icon">${icon('mail')}</span><span><strong>${esc(n.title)}</strong><span class="notice-detail">${fmtDate(n.date)} · ${esc(n.time)} · ${n.recipients.length} destinatário(s)</span><span class="tag">Prévia · não enviado</span></span><span class="notice-created">${new Date(n.createdAt).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'})}</span>${icon('right')}</button>`).join('')}</section>`:empty('Nenhum aviso por enquanto','Adicione, edite ou exclua um compromisso para conferir como ficará o aviso por e-mail.','')}`;}
function render(){const r=route(),personal=r==='visao-geral'&&ui.scope==='mine',titles={'visao-geral':personal?'Minha semana':'Olá, família!',calendario:'Calendário',tarefas:'Tarefas',compras:'Lista de compras',familia:'Nossa família',configuracoes:'Configurações',avisos:'Avisos do calendário'},subtitles={'visao-geral':personal?`Olá, ${current().name}! Seus compromissos e tarefas, em um só lugar.`:'Sua semana em família, organizada em um só lugar.',calendario:'Tempo para o que importa, junto de quem importa.',tarefas:'Cada um faz sua parte. A semana fica mais leve.',compras:'Uma lista compartilhada para ninguém esquecer de nada.',familia:'Pequenos cuidados, uma família mais organizada.',configuracoes:'Pequenos ajustes para uma rotina mais leve.',avisos:'Acompanhe as mudanças nos compromissos da família.'},newType=({calendario:'events',tarefas:'tasks',compras:'shopping',familia:'members'})[r];document.documentElement.classList.toggle('large-text',data.settings.largeText);document.title=`${titles[r]} · FamilyCalendar`;app.innerHTML=`<aside class="sidebar"><a class="brand" href="#visao-geral" aria-label="FamilyCalendar, início"><img src="./assets/logo.svg" width="55" height="55" alt=""><span>FamilyCalendar<small>1.0 · a vida em família</small></span></a><nav aria-label="Navegação principal">${navs.map(([key,label,ic])=>`<a href="#${key}" ${r===key?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></a>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-thought">${icon('leaf')}<p>Mais organização.<br>Mais tempo juntos.</p></div><a href="#configuracoes" class="settings-link ${r==='configuracoes'?'active':''}">${icon('settings')}Configurações</a><span class="prototype-label">Protótipo interativo</span></div></aside><main id="main" tabindex="-1"><header class="page-header"><div><span class="eyebrow">UM LUGAR PARA A SUA FAMÍLIA</span><h1>${esc(titles[r])}</h1><p>${esc(subtitles[r])}</p></div><div class="header-actions">${newType?`<button class="button primary header-add" data-action="new" data-type="${newType}">${icon('plus')}<span>${({events:'Novo compromisso',tasks:'Nova tarefa',shopping:'Adicionar item',members:'Adicionar integrante'})[newType]}</span></button>`:r==='visao-geral'?`<button class="button primary header-add" data-action="add-menu">${icon('plus')}<span>Adicionar</span></button>`:''}<a href="#avisos" class="icon-button bell-button ${r==='avisos'?'active':''}" aria-label="Avisos do calendário${data.notices.some(n=>!n.read)?', há novos avisos':''}">${icon('bell')}${data.notices.some(n=>!n.read)?'<span class="unread-dot"></span>':''}</a><label class="profile-selector">${avatar(current())}<select data-action="profile" aria-label="Trocar perfil em uso">${data.members.map(m=>`<option value="${esc(m.id)}" ${m.id===current().id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label></div></header><div class="save-status ${storageOK?'':'save-warning'}"><span class="status-dot ${storageOK?'sage':'peach'}"></span>${storageOK?'Salvo neste navegador':'Armazenamento indisponível: baixe uma cópia nas configurações'}</div><div class="page-content">${r==='visao-geral'?overview():r==='calendario'?calendarPage():r==='tarefas'?tasksPage():r==='compras'?shoppingPage():r==='familia'?familyPage():r==='configuracoes'?settingsPage():noticesPage()}</div><footer class="app-footer"><span>FamilyCalendar <span class="muted">1.0</span></span><a href="#configuracoes">Sobre este protótipo</a></footer></main><nav class="mobile-nav" aria-label="Navegação no celular">${navs.map(([key,label,ic])=>`<a href="#${key}" ${r===key?'aria-current="page"':''}>${icon(ic)}<span>${key==='visao-geral'?'Geral':key==='compras'?'Compras':label}</span></a>`).join('')}<a href="#configuracoes" ${r==='configuracoes'?'aria-current="page"':''}>${icon('settings')}<span>Ajustes</span></a></nav>`;}

function dialogHeader(title,subtitle=''){return `<div class="dialog-header"><div><h2 id="dialog-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-button" type="button" data-action="close-dialog" aria-label="Fechar janela">${icon('close')}</button></div>`;}
function openDialog(html,state={}){dialogState=state;modal.innerHTML=html;if(!modal.open)modal.showModal();const first=modal.querySelector('input:not([type="checkbox"]),select,button');setTimeout(()=>first?.focus(),0);}
function closeDialog(){modal.close();dialogState=null;}
function memberFields(selected){return `<fieldset class="people-picker"><legend>Quem participa?</legend>${[{id:'all',name:'Toda a família'},...data.members].map(m=>`<label class="person-choice"><input type="checkbox" name="members" value="${esc(m.id)}" ${selected.includes(m.id)?'checked':''}>${m.id==='all'?icon('family'):avatar(m,'tiny')}<span>${esc(m.name)}</span></label>`).join('')}</fieldset>`;}
function editor(type,id=null,date=null){const rec=id?data[type].find(r=>r.id===id):null;if(id&&!rec)return;const defaultDate=date||(weekDays(ui.anchor).includes(todayKey())?todayKey():monday(ui.anchor)),m=activeMember();const r=rec||(type==='members'?{name:'',email:'',notify:true,color:'sage',avatar:'initials'}:{title:'',date:defaultDate,members:type==='shopping'?['all']:[m||'all'],time:'09:00',end:'10:00',notes:'',done:false,qty:'',category:'Mercado'});const names={events:['compromisso','Novo compromisso'],tasks:['tarefa','Nova tarefa'],shopping:['item','Adicionar item'],members:['integrante','Adicionar integrante']};const title=rec?`Editar ${names[type][0]}`:names[type][1];let fields='';
  if(type==='members')fields=`<label>Nome<input name="name" required maxlength="50" value="${esc(r.name)}" placeholder="Como a pessoa gosta de ser chamada?" autocomplete="off"></label><label>E-mail<input name="email" type="email" maxlength="254" value="${esc(r.email)}" placeholder="nome@exemplo.com" autocomplete="off"><small>Usado somente nas prévias dos avisos deste protótipo.</small></label><label>Cor do perfil<select name="color">${[['sage','Verde sálvia'],['blue','Azul suave'],['lavender','Lavanda'],['peach','Pêssego']].map(([v,l])=>`<option value="${v}" ${r.color===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="checkbox-field"><input class="check" type="checkbox" name="notify" ${r.notify?'checked':''}>Receber avisos de alterações no calendário</label>`;
  else fields=`<label>${type==='shopping'?'O que precisamos comprar?':type==='tasks'?'O que precisa ser feito?':'Nome do compromisso'}<input name="title" required maxlength="120" value="${esc(r.title)}" placeholder="${type==='events'?'Ex.: almoço em família':type==='tasks'?'Ex.: regar as plantas':'Ex.: leite'}" autocomplete="off"></label><div class="form-row"><label>${type==='shopping'?'Dia da compra':'Data'}<input type="date" name="date" required value="${esc(r.date)}"></label>${type==='shopping'?`<label>Quantidade<input name="qty" maxlength="50" value="${esc(r.qty)}" placeholder="Ex.: 2 litros"></label>`:''}</div>${type==='events'?`<div class="form-row"><label>Início<input type="time" name="time" required value="${esc(r.time)}"></label><label>Fim<input type="time" name="end" required value="${esc(r.end)}"></label></div>${memberFields(r.members)}<label>Observações <span class="muted">(opcional)</span><textarea name="notes" maxlength="2000" rows="3" placeholder="Local, o que levar ou outros detalhes">${esc(r.notes)}</textarea></label><div class="form-note">${icon('mail')}Ao salvar, uma prévia do aviso aparecerá na campainha. Não há envio real de e-mail.</div>`:type==='tasks'?`${memberFields(r.members)}<label class="checkbox-field"><input class="check" type="checkbox" name="done" ${r.done?'checked':''}>Tarefa concluída</label>`:`<label>Categoria<select name="category">${CATEGORIES.map(c=>`<option ${c===r.category?'selected':''}>${c}</option>`).join('')}</select></label><label class="checkbox-field"><input class="check" type="checkbox" name="done" ${r.done?'checked':''}>Já foi comprado</label><div class="form-note">${icon('family')}Este item faz parte da lista compartilhada da família.</div>`}`;
  openDialog(`${dialogHeader(title)}<form id="editor-form" class="editor-form">${fields}<p class="form-error" role="alert" hidden></p><div class="dialog-footer">${rec?`<button class="text-link danger" type="button" data-action="delete" data-type="${type}" data-id="${esc(rec.id)}">${icon('trash')}Excluir</button>`:'<span></span>'}<div><button class="button outline" type="button" data-action="close-dialog">Cancelar</button><button class="button primary" type="submit">${rec?'Salvar alterações':type==='members'?'Adicionar integrante':'Adicionar'}</button></div></div></form>`,{type,id});
}
function error(message){const e=modal.querySelector('.form-error');e.textContent=message;e.hidden=false;}
function showAddMenu(){openDialog(`${dialogHeader('O que vamos organizar?','Escolha o que deseja adicionar à semana.')}<div class="add-options">${[['events','calendar','Compromisso','Um encontro, uma consulta, um momento juntos.'],['tasks','check','Tarefa','Algo para fazer e alguém para ajudar.'],['shopping','cart','Item de compra','O que está faltando para a família.']].map(([t,ic,title,text])=>`<button class="add-option" data-action="new" data-type="${t}">${icon(ic)}<span><strong>${title}</strong><small>${text}</small></span>${icon('right')}</button>`).join('')}</div>`);}
function confirmDialog(title,text,action,type='',id=''){openDialog(`${dialogHeader(title)}<p class="confirm-copy">${esc(text)}</p><div class="dialog-footer"><button class="button outline" data-action="close-dialog">Cancelar</button><button class="button danger-button" data-action="${action}" data-type="${type}" data-id="${esc(id)}">${action==='do-reset'?'Restaurar exemplos':'Excluir'}</button></div>`);}
function showNotice(id){const n=data.notices.find(n=>n.id===id);if(!n)return;data={...data,notices:data.notices.map(x=>x.id===id?{...x,read:true}:x)};save();openDialog(`${dialogHeader('Prévia do e-mail','Demonstração · esta mensagem não foi enviada')}<div class="email-preview"><dl><dt>Para</dt><dd>${esc(n.recipients.join(', '))}</dd><dt>Assunto</dt><dd>${esc(n.title)}</dd></dl><pre>${esc(noticeBody(n))}</pre></div><div class="dialog-footer"><button class="button outline" data-action="close-dialog">Fechar</button><button class="button primary" data-action="copy-notice" data-id="${esc(n.id)}">${icon('copy')}Copiar mensagem</button></div>`);}
function download(text,name,type){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}

document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,type=el.dataset.type,id=el.dataset.id;
  if(action==='new')editor(type,null,el.dataset.date);
  else if(action==='edit')editor(type,id);
  else if(action==='add-menu')showAddMenu();
  else if(action==='close-dialog')closeDialog();
  else if(action==='prev'||action==='next'){const n=action==='prev'?-1:1;if(isMonth()){const d=asDate(ui.anchor);ui.anchor=dateKey(new Date(d.getFullYear(),d.getMonth()+n,1,12));}else ui.anchor=addDays(ui.anchor,n*7);render();}
  else if(action==='today'){ui.anchor=todayKey();render();}
  else if(action==='segment'){ui[el.dataset.group]=el.dataset.value;render();}
  else if(action==='filter-person'){ui.member=ui.member===id?'all':id;ui.scope='family';render();}
  else if(action==='use-profile'){data={...data,currentMember:id};ui.scope='mine';ui.member='all';save();location.hash='visao-geral';render();}
  else if(action==='delete'){const r=data[type].find(r=>r.id===id);if(type==='members'&&data.members.length===1){error('A família precisa ter pelo menos um integrante.');return;}if(type==='members'&&[...data.events,...data.tasks].some(r=>r.members.includes(id))){error('Antes de excluir este perfil, edite os compromissos e as tarefas atribuídos a ele e escolha outro responsável.');return;}confirmDialog(`Excluir ${type==='members'?'integrante':type==='events'?'compromisso':type==='tasks'?'tarefa':'item'}?`,`“${r.title||r.name}” será removido${type==='events'?'. Será gerada uma prévia do aviso à família.':'.'}`,'do-delete',type,id);}
  else if(action==='do-delete'){const r=data[type].find(r=>r.id===id);if(!r)return;data=removeRecord(data,type,id);if(type==='events')data=calendarNotice(data,r,'excluído');if(type==='members'){if(data.currentMember===id)data.currentMember=data.members[0].id;if(ui.member===id)ui.member='all';}closeDialog();save('Removido com sucesso.');}
  else if(action==='notice')showNotice(id);
  else if(action==='read-all'){data={...data,notices:data.notices.map(n=>({...n,read:true}))};save('Todos os avisos foram marcados como lidos.');}
  else if(action==='copy-notice'){try{const n=data.notices.find(n=>n.id===id);await navigator.clipboard.writeText(`Assunto: ${n.title}\nPara: ${n.recipients.join(', ')}\n\n${noticeBody(n)}`);toast('Mensagem copiada.');}catch{toast('Não foi possível copiar. Você pode selecionar o texto da prévia.');}}
  else if(action==='export-calendar'){const evs=isMonth()?data.events.filter(e=>e.date.slice(0,7)===ui.anchor.slice(0,7)&&isFor(e,activeMember())):recordsInWeek(data.events,ui.anchor,activeMember());download(calendarICS(evs),'familycalendar.ics','text/calendar;charset=utf-8');toast('Calendário baixado para importar no seu aplicativo de agenda.');}
  else if(action==='export-data'){download(JSON.stringify(data,null,2),`familycalendar-${todayKey()}.json`,'application/json');toast('Cópia dos dados baixada. Guarde em um lugar seguro.');}
  else if(action==='reset')confirmDialog('Restaurar a demonstração?','As alterações deste navegador serão substituídas pelos dados de exemplo. Baixe uma cópia antes, se quiser guardar.','do-reset');
  else if(action==='do-reset'){data=seedState();Object.assign(ui,{anchor:todayKey(),member:'all',scope:'family',search:'',status:'all',category:'all'});closeDialog();save('Demonstração restaurada.');}
});
document.addEventListener('change',async ev=>{const el=ev.target,a=el.dataset.action;
  if(a==='toggle'){const col=el.dataset.type;data={...data,[col]:data[col].map(t=>t.id===el.dataset.id?{...t,done:el.checked}:t)};save(el.checked?(col==='tasks'?'Tarefa concluída. Bom trabalho!':'Item marcado como comprado.'):'Item reaberto.');}
  else if(a==='profile'){data={...data,currentMember:el.value};save(`Perfil de ${current().name} selecionado.`);}
  else if(a==='member-filter'){ui.member=el.value;render();}
  else if(a==='category'){ui.category=el.value;render();}
  else if(a==='setting'){data={...data,settings:{...data.settings,[el.dataset.key]:el.checked}};save('Preferência salva.');}
  else if(a==='jump-date'&&el.value){ui.anchor=el.value;render();}
  else if(el.id==='import-file'&&el.files[0]){const f=el.files[0];try{if(f.size>5*1024*1024)throw new Error('Escolha um arquivo de até 5 MB.');const imported=validateState(JSON.parse(await f.text()));openDialog(`${dialogHeader('Importar cópia dos dados?')}<p class="confirm-copy">Esta cópia contém ${imported.members.length} integrantes, ${imported.events.length} compromissos, ${imported.tasks.length} tarefas e ${imported.shopping.length} itens de compra. Os dados atuais serão substituídos.</p><div class="dialog-footer"><button class="button outline" data-action="close-dialog">Cancelar</button><button class="button primary" id="confirm-import">Importar dados</button></div>`);$('#confirm-import').addEventListener('click',()=>{data=imported;ui.member='all';if(ui.scope==='mine')ui.scope='family';closeDialog();save('Cópia importada com sucesso.');});}catch(e){toast(e instanceof SyntaxError?'O arquivo não contém um JSON válido.':e.message);}el.value='';}
  if(el.name==='members'&&el.type==='checkbox'){const checks=[...modal.querySelectorAll('input[name="members"]')];if(el.value==='all'&&el.checked)checks.filter(x=>x!==el).forEach(x=>x.checked=false);else if(el.checked)checks.find(x=>x.value==='all').checked=false;}
});
document.addEventListener('input',ev=>{if(!ev.target.matches('[data-search]'))return;const value=ev.target.value,pos=ev.target.selectionStart;ui.search=value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{render();const el=$('[data-search]');el?.focus();try{el?.setSelectionRange(pos,pos);}catch{}},180);});
document.addEventListener('submit',ev=>{if(!['editor-form','quick-add'].includes(ev.target.id))return;ev.preventDefault();const f=new FormData(ev.target);
  if(ev.target.id==='quick-add'){const title=String(f.get('title')).trim();if(!title){toast('Escreva o nome do item.');return;}const rec={id:uid(),title,date:String(f.get('date')),qty:String(f.get('qty')).trim(),category:ui.category==='all'?'Mercado':ui.category,done:false,members:['all']};data=upsert(data,'shopping',rec);ui.anchor=rec.date;ui.search='';ui.status='all';save('Item adicionado à lista da família.');$('#quick-add input[name="title"]')?.focus();return;}
  const {type,id}=dialogState,old=id?data[type].find(r=>r.id===id):null;let r;
  if(type==='members'){const name=String(f.get('name')).trim();if(!name){error('Informe o nome do integrante.');return;}r={id:id||uid(),name,email:String(f.get('email')).trim(),color:String(f.get('color')),notify:f.has('notify'),avatar:old?.avatar||'initials'};}
  else {const title=String(f.get('title')).trim(),members=type==='shopping'?['all']:f.getAll('members');if(!title){error('Dê um nome a este item.');return;}if(!members.length){error('Escolha pelo menos um integrante ou toda a família.');return;}r={id:id||uid(),title,date:String(f.get('date')),members};if(type==='events'){const time=String(f.get('time')),end=String(f.get('end'));if(end<=time){error('O horário de fim deve ser depois do início, no mesmo dia.');return;}r={...r,time,end,notes:String(f.get('notes')).trim()};}else {r.done=f.has('done');if(type==='shopping')r={...r,qty:String(f.get('qty')).trim(),category:String(f.get('category'))};}}
  data=upsert(data,type,r);if(type==='events')data=calendarNotice(data,r,old?'alterado':'criado');if(type!=='members')ui.anchor=r.date;closeDialog();save(type==='events'?(data.settings.emailPreviews?'Compromisso salvo. Confira a prévia do aviso na campainha.':'Compromisso salvo.'):'Salvo. Tudo organizado!');
});
modal.addEventListener('click',ev=>{if(ev.target!==modal)return;const r=modal.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)closeDialog();});
modal.addEventListener('close',()=>{dialogState=null;});
window.addEventListener('hashchange',()=>{ui.search='';ui.status='all';ui.category='all';render();window.scrollTo({top:0});});
window.addEventListener('storage',ev=>{if(ev.key!==STORAGE_KEY||!ev.newValue)return;try{data=validateState(JSON.parse(ev.newValue));if(!data.members.some(m=>m.id===ui.member))ui.member='all';render();toast('Atualizações de outra aba carregadas.');}catch{toast('Não foi possível carregar as alterações de outra aba.');}});
render();
try {if(!localStorage.getItem(STORAGE_KEY))localStorage.setItem(STORAGE_KEY,JSON.stringify(data));}catch{storageOK=false;render();}
